{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Atazanavir, a related HIV protease inhibitor, has oral bioavailability >90% when taken with food; the query is a peptidomimetic HIV protease inhibitor assessed in the fed state, supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Atazanavir's human oral bioavailability is 60-68%, providing direct numeric evidence that this inhibitor class can exceed the 20% threshold; the query shares the hydroxyethylene core and carbamate/urea functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Amprenavir has >70% oral bioavailability in humans and contains a carbamate and hydroxyethylene-like motif, supporting high F for the query's similar carbamate-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Darunavir has 37% oral bioavailability when given alone, above the 20% threshold, despite CYP3A4/P-gp liabilities; this supports F >=20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "KNI-272, a thiazole-containing peptidomimetic HIV protease inhibitor, achieved 54.97% absolute oral bioavailability at 10 mg/kg, supporting high F for the thiazole-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Lopinavir, the closest analogue by Morgan similarity, has low oral bioavailability due to CYP3A4 metabolism and P-gp efflux; this is contradictory evidence, but the query's thiazole carbamate/urea differs from lopinavir's phenoxyacetyl/cyclic urea and is more consistent with higher-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ritonavir, a peptidomimetic HIV protease inhibitor with a thiazole carbamate/urea scaffold. Although the closest retrieved analogue lopinavir has low oral bioavailability, multiple direct HIV protease inhibitor analogues (atazanavir 60-68% and >90% with food, amprenavir >70%, darunavir 37%, KNI-272 ~55%) demonstrate that this structural class can meet the F>=20% threshold, and ritonavir itself is known to have adequate oral bioavailability. Fed-state conditions further favor absorption, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental record for ritonavir itself was retrieved; the closest analogue lopinavir is low-F, so the prediction relies on structural analogy and known pharmacology.",
    "Lopinavir low-F records are qualitative and do not provide a numeric F relative to the 20% threshold.",
    "Fed-state absolute oral bioavailability for the query is not directly reported in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

